void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;
    rephase_limit += 4096;

    // Perform phase saving update with probability based on recent performance
    if (fast_lbd_sum > 0 && lbd_queue_size > 0) {
        double fast_avg = fast_lbd_sum / lbd_queue_size;
        double slow_avg = slow_lbd_sum / conflicts;

        // If recent conflicts are significantly worse than historical average,
        // more aggressively change phases to escape local minima
        if (fast_avg > 1.5 * slow_avg) {
            // Reset to random phases with higher probability
            for (int i = 1; i <= vars; i++) {
                saved[i] = (rand() % 2 ? 1 : -1);
            }
        } else if (fast_avg > slow_avg) {
            // Mild degradation - use local best phases inverted
            for (int i = 1; i <= vars; i++) {
                saved[i] = -local_best[i];
            }
        } else {
            // Good performance - stick with local best phases
            for (int i = 1; i <= vars; i++) {
                saved[i] = local_best[i];
            }
        }
    } else {
        // No LBD data yet - use default random phase assignment
        for (int i = 1; i <= vars; i++) {
            saved[i] = (rand() % 2 ? 1 : -1);
        }
    }
}
